#include <stdio.h>

typedef enum { CLOSED, OPEN, HALF_OPEN } CBState;

typedef struct {
    CBState state;
    int failure_count;
    int failure_threshold;
} CircuitBreaker;

void cb_init(CircuitBreaker *cb) {
    cb->state = CLOSED; cb->failure_count = 0; cb->failure_threshold = 3;
}

int cb_call(CircuitBreaker *cb, int (*fn)()) {
    if (cb->state == OPEN) { printf("Circuit open, rejecting\n"); return -1; }
    int result = fn();
    if (result < 0) {
        cb->failure_count++;
        printf("Failure %d/%d\n", cb->failure_count, cb->failure_threshold);
        if (cb->failure_count >= cb->failure_threshold) {
            cb->state = OPEN;
            printf("Circuit OPEN\n");
        }
        return result;
    }
    cb->failure_count = 0;
    if (cb->state == HALF_OPEN) {
        cb->state = CLOSED;
        printf("Circuit CLOSED (reset)\n");
    }
    return result;
}

int success() { return 200; }
int failure() { return -1; }

int main() {
    CircuitBreaker cb;
    cb_init(&cb);
    cb_call(&cb, success); cb_call(&cb, success);
    cb_call(&cb, failure); cb_call(&cb, failure); cb_call(&cb, failure);
    cb.state = HALF_OPEN; // simulate timeout
    printf("Half-open attempt\n");
    cb_call(&cb, success);
    printf("State: %d\n", cb.state);
    return 0;
}
